def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    import heapq

    if not jobs:
        return 0

    times = sorted({time for start, end, _ in jobs for time in (start, end)})
    index = {time: i for i, time in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, capacity, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path distances are easy to compute in time order.
    potential = [0] * n
    for u in range(n):
        for v, capacity, cost, _ in graph[u]:
            if capacity and v > u:
                potential[v] = min(potential[v], potential[u] + cost)

    total_cost = 0
    flow = 0
    infinity = float("inf")

    while flow < k:
        distance = [infinity] * n
        previous = [None] * n
        distance[0] = 0
        heap = [(0, 0)]

        while heap:
            dist, u = heapq.heappop(heap)
            if dist != distance[u]:
                continue

            for edge_index, (v, capacity, cost, _) in enumerate(graph[u]):
                if not capacity:
                    continue
                new_dist = dist + cost + potential[u] - potential[v]
                if new_dist < distance[v]:
                    distance[v] = new_dist
                    previous[v] = (u, edge_index)
                    heapq.heappush(heap, (new_dist, v))

        for v in range(n):
            if distance[v] < infinity:
                potential[v] += distance[v]

        amount = k - flow
        v = n - 1
        while v != 0:
            u, edge_index = previous[v]
            amount = min(amount, graph[u][edge_index][1])
            v = u

        v = n - 1
        while v != 0:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            total_cost += amount * edge[2]
            edge[1] -= amount
            graph[v][edge[3]][1] += amount
            v = u

        flow += amount

    return -total_cost
